import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sources = [
  "workbench.css",
  "workbench-v5.css",
  "workbench-v8-multigroup.css",
  "v26-final.css",
  "v27-final.css",
  "v28-final.css",
  "v29-consistency.css",
  "v30-entry.css",
  "v31-blue-final.css",
  "v32-duplicate-guard.css",
];

const banner = [
  "/* SOUS unified UI stylesheet.",
  " * Generated by scripts/build-styles.mjs.",
  " * Edit source styles, then run npm run build:styles.",
  " */",
  "",
].join("\n");

const body = sources
  .map((file) => {
    const source = fs.readFileSync(path.join(projectDir, file), "utf8").trim();
    return `/* ===== ${file} ===== */\n${source}\n`;
  })
  .join("\n");

fs.writeFileSync(path.join(projectDir, "sous-ui.css"), `${banner}${body}`, "utf8");
console.log(`Built sous-ui.css from ${sources.length} source stylesheets.`);


